<?php
require_once __DIR__ . '/config.php'; require_once __DIR__ . '/includes/role_check.php'; require_role(['admin']);
$message=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  require_csrf();
  if(isset($_POST['assign_department'])){$cid=(int)$_POST['complaint_id'];$did=(int)$_POST['department_id'];$q=$conn->prepare('SELECT user_id FROM complaints WHERE id=?');$q->bind_param('i',$cid);$q->execute();$row=$q->get_result()->fetch_assoc();$q->close();$d=$conn->prepare('SELECT id FROM departments WHERE id=? AND is_active=1');$d->bind_param('i',$did);$d->execute();$valid=$d->get_result()->fetch_assoc();$d->close();if($row&&$valid){$u=$conn->prepare('UPDATE complaints SET department_id=?, officer_id=NULL WHERE id=?');$u->bind_param('ii',$did,$cid);$u->execute();$u->close();$actor=(int)$_SESSION['user_id'];$action='Department Assigned';$desc='Administrator routed the complaint to a department.';$tl=$conn->prepare('INSERT INTO complaint_timeline (complaint_id,user_id,action,new_value,description) VALUES (?,?,?,?,?)');$tl->bind_param('iisss',$cid,$actor,$action,$did,$desc);$tl->execute();$tl->close();audit_log($conn,'assign_department','complaint',$cid,'Administrator routed complaint to department '.$did);$message='Complaint routed successfully.';}}
  if(isset($_POST['create_account'])){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$role=$_POST['role']??'';$did=(int)($_POST['department_id']??0);$pw=$_POST['password']??'';if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&in_array($role,['department','officer'],true)&&strlen($pw)>=8&&$did>0){$hash=password_hash($pw,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(full_name,email,password,role,department_id) VALUES(?,?,?,?,?)');$s->bind_param('ssssi',$name,$email,$hash,$role,$did);if($s->execute()){audit_log($conn,'create_account','user',null,'Administrator created '.$role.' account for '.$email);$message='Account created.';}else $error='Email may already be in use.';$s->close();}else $error='Provide valid details and a password of at least 8 characters.';}
}
$departments=$conn->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetch_all(MYSQLI_ASSOC);$complaints=$conn->query("SELECT c.*,u.full_name user_name,d.name department_name FROM complaints c JOIN users u ON u.id=c.user_id LEFT JOIN departments d ON d.id=c.department_id ORDER BY c.created_at DESC")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Workflow | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"></head><body class="bg-light"><div class="d-flex min-vh-100"><?php include 'includes/sidebar.php';?><main class="flex-grow-1"><header class="bg-white border-bottom p-3"><h4 class="mb-0">Admin Workflow Console</h4><small class="text-muted">Route complaints and provision department / officer accounts</small></header><div class="container-fluid p-4"><?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="row g-4 mb-4"><div class="col-xl-7"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Complaint routing</div><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Complaint</th><th>Status</th><th>Department</th><th>Route</th></tr></thead><tbody><?php foreach($complaints as $c):?><tr><td><a href="view_complaint.php?id=<?=$c['id']?>"><?=htmlspecialchars($c['subject'])?></a><div class="small text-muted">#<?=$c['id']?> · <?=htmlspecialchars($c['user_name'])?></div></td><td><span class="badge text-bg-<?=status_badge_class($c['status'])?>"><?=$c['status']?></span></td><td><?=htmlspecialchars($c['department_name']??'Unassigned')?></td><td><form class="d-flex gap-2" method="post"><?=csrf_field()?><input type="hidden" name="complaint_id" value="<?=$c['id']?>"><select class="form-select form-select-sm" name="department_id" required><option value="">Select</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>" <?=$c['department_id']==$d['id']?'selected':''?>><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary" name="assign_department">Route</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div><div class="col-xl-5"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Create role account</div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="full_name" required></div><div class="mb-3"><label class="form-label">Email</label><input class="form-control" name="email" type="email" required></div><div class="mb-3"><label class="form-label">Role</label><select class="form-select" name="role" required><option value="department">Department manager</option><option value="officer">Complaint officer</option></select></div><div class="mb-3"><label class="form-label">Department</label><select class="form-select" name="department_id" required><option value="">Select department</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Temporary password</label><input class="form-control" name="password" type="password" minlength="8" required></div><button class="btn btn-dark w-100" name="create_account"><i class="bi bi-person-plus me-1"></i>Create account</button></form></div></div></div></div></div></main></div></body></html>
